"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Dialog, DialogActions, DialogClose, DialogSurface, DialogTrigger, useDialog } from "@/components/ui/dialog"
import { Fraction } from "@/components/ui/fraction"

/** A sheet from below. Same props and behaviour as Dialog. */
const Drawer = Dialog
const DrawerTrigger = DialogTrigger
const DrawerClose = DialogClose

/** How far the arc is pulled before a let-go puts the drawer away. Solid's is its own silence, measured. */
const AWAY = 90
const KNOBS = ["--pull", "--solid", "--sink"]

type Thirds = { third: number; setThird: (n: number) => void }

/** The fermata's arc. Drag it down to put the drawer away; a tap or Enter does the same. */
function DrawerHandle({ label, thirds }: { label: string; thirds?: Thirds }) {
  const { open, setOpen } = useDialog()
  const button = React.useRef<HTMLButtonElement>(null)
  const from = React.useRef<number | null>(null)
  const pulled = React.useRef(0)
  const give = React.useRef(AWAY)
  // A drawer put away by a drag keeps its pull until it's opened again.
  React.useEffect(() => {
    const d = button.current?.closest("dialog")
    if (open) KNOBS.forEach((p) => d?.style.removeProperty(p))
  }, [open])
  const surface = (e: React.SyntheticEvent) => e.currentTarget.closest("dialog") as HTMLDialogElement
  const step = (n: number) => thirds?.setThird(Math.min(3, Math.max(1, n)))

  const letGo = (e: React.PointerEvent<HTMLButtonElement>) => {
    if (from.current === null) return
    from.current = null
    const d = surface(e)
    const moved = Math.abs(pulled.current) >= 4
    if (thirds && e.type === "pointerup") {
      // Land on the nearest third; lower than half a third, it goes away. A tap raises it a third, round to one.
      const third = parseFloat(getComputedStyle(d).maxHeight) / 3
      const at = d.getBoundingClientRect().height / third
      d.removeAttribute("data-pulling")
      d.style.removeProperty("--pull")
      if (!moved) return step((thirds.third % 3) + 1)
      if (at < 0.5) return setOpen(false)
      return step(Math.round(at))
    }
    d.removeAttribute("data-pulling")
    if (e.type === "pointerup" && (pulled.current >= give.current || !moved)) setOpen(false)
    else KNOBS.forEach((p) => d.style.setProperty(p, p === "--solid" ? "0" : "0px"))
  }

  return (
    <button
      ref={button}
      type="button"
      data-slot="drawer-handle"
      aria-label={label}
      className="db-drawer-handle"
      {...(thirds && {
        role: "slider",
        "aria-orientation": "vertical" as const,
        "aria-valuemin": 1,
        "aria-valuemax": 3,
        "aria-valuenow": thirds.third,
        "aria-valuetext": `${thirds.third} of 3`,
      })}
      onPointerDown={(e) => {
        from.current = e.clientY
        pulled.current = 0
        e.currentTarget.setPointerCapture(e.pointerId)
        const d = surface(e)
        d.setAttribute("data-pulling", "")
        give.current = AWAY
        if (d.dataset.variant === "solid") {
          // Its give is the silence it holds: the height it loses once set solid. Measured unseen, in one frame.
          const at = d.getBoundingClientRect().height
          d.style.setProperty("--solid", "1")
          give.current = Math.max(24, at - d.getBoundingClientRect().height)
          d.style.setProperty("--solid", "0")
        }
      }}
      onPointerMove={(e) => {
        if (from.current === null) return
        const d = surface(e)
        // Thirds follows the hand both ways; the others only down.
        pulled.current = thirds ? e.clientY - from.current : Math.max(0, e.clientY - from.current)
        d.style.setProperty("--pull", `${pulled.current}px`)
        d.style.setProperty("--solid", String(Math.min(1, pulled.current / give.current)))
        d.style.setProperty("--sink", `${Math.max(0, pulled.current - give.current)}px`)
      }}
      onPointerUp={letGo}
      onPointerCancel={letGo}
      onKeyDown={(e) => {
        if (!thirds) return
        const to = { ArrowUp: thirds.third + 1, ArrowRight: thirds.third + 1, ArrowDown: thirds.third - 1, ArrowLeft: thirds.third - 1, Home: 1, End: 3 }[e.key]
        if (to === undefined) return
        e.preventDefault()
        step(to)
      }}
      onClick={(e) => {
        if (e.detail !== 0) return
        // The keyboard: Enter puts it away; in thirds it raises it a third, round to one.
        if (thirds) step((thirds.third % 3) + 1)
        else setOpen(false)
      }}
    >
      <svg viewBox="0 0 40 22" aria-hidden="true">
        <path d="M3 20 A17 17 0 0 1 37 20" />
        <circle cx="20" cy="17" r="2.6" />
      </svg>
    </button>
  )
}

type DrawerContentProps = React.ComponentProps<"dialog"> & {
  /** The accessible name of the arc that puts the drawer away (in thirds, that sets its height). */
  handleLabel?: string
  /**
   * arc: it rises and you drag the arc down to put it away. thirds: it stops at a third, two thirds or the
   * whole height, and the share stands in the corner as a fraction. solid: pulling the arc first takes out
   * the silence between its parts, as a compositor sets type solid; only then does it go.
   */
  variant?: "arc" | "thirds" | "solid"
}

function DrawerContent({ className, children, handleLabel, variant = "arc", style, ...props }: DrawerContentProps) {
  const { open } = useDialog()
  const [third, setThird] = React.useState(1)
  // Every opening starts at a third: reset while rendering the change, not in an effect after it.
  const [was, setWas] = React.useState(open)
  if (open !== was) {
    setWas(open)
    if (open) setThird(1)
  }
  const thirds = variant === "thirds" ? { third, setThird } : undefined
  return (
    <DialogSurface
      data-slot="drawer-content"
      data-variant={variant === "arc" ? undefined : variant}
      className={cn("db-drawer", className)}
      style={thirds ? ({ "--third": third, ...style } as React.CSSProperties) : style}
      {...props}
    >
      <DrawerHandle label={handleLabel ?? (thirds ? "Height of the drawer" : "Put this away")} thirds={thirds} />
      {thirds && (
        <span className="db-drawer-share" aria-hidden="true">
          <Fraction count={third} total={3} />
        </span>
      )}
      <div data-slot="drawer-body" className="db-drawer-body">
        {children}
      </div>
    </DialogSurface>
  )
}

function DrawerTitle({ className, ...props }: React.ComponentProps<"h2">) {
  const { titleId } = useDialog()
  return <h2 data-slot="drawer-title" id={titleId} className={cn("db-drawer-title", className)} {...props} />
}

function DrawerDescription({ className, ...props }: React.ComponentProps<"p">) {
  const { descriptionId } = useDialog()
  return <p data-slot="drawer-description" id={descriptionId} className={className} {...props} />
}

function DrawerActions(props: React.ComponentProps<"div">) {
  return <DialogActions data-slot="drawer-actions" {...props} />
}

export { Drawer, DrawerTrigger, DrawerContent, DrawerTitle, DrawerDescription, DrawerActions, DrawerActions as DrawerFooter, DrawerClose, type DrawerContentProps }

@layer components {
  /* ── db-drawer ── a sheet from below, lifted by the fermata's arc.
     The backdrop lives in dialog.css. --pull is set while the arc is dragged. */
  .db-drawer {
    position: fixed; inset: auto 0 0; margin: 0; width: 100%; max-width: none; max-height: 85dvh;
    padding: 0 var(--db-margin) var(--db-space-7); overflow: auto;
    border: 0; border-top: var(--db-hairline) solid var(--db-ink); background: var(--db-paper); color: var(--db-graphite);
    box-shadow: 0 12rem 0 var(--db-paper); /* paper under the rebound, not a shadow */
    translate: 0 100%;
    transition: translate var(--db-andante) var(--db-spiccato), overlay var(--db-andante) allow-discrete, display var(--db-andante) allow-discrete;
  }
  .db-drawer[open] { translate: 0 var(--pull, 0px); }
  @starting-style { .db-drawer[open] { translate: 0 100%; } }
  .db-drawer[data-pulling] { transition: none; }
  .db-drawer-handle { display: block; margin: 0 auto var(--db-space-4); padding: var(--db-space-4) var(--db-space-6) var(--db-space-2); border: 0; background: none; color: var(--db-ink); cursor: grab; touch-action: none; }
  .db-drawer-handle:active { cursor: grabbing; }
  .db-drawer-handle svg { width: 40px; height: 22px; overflow: visible; }
  .db-drawer-handle path { fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; }
  .db-drawer-handle circle { fill: var(--db-accent); }
  .db-drawer-body { display: grid; justify-items: start; gap: var(--db-space-6); max-width: 40rem; margin-inline: auto; }
  .db-drawer-title { font-size: var(--db-mf); line-height: var(--db-mf-lh); letter-spacing: var(--db-mf-tr); font-weight: 300; color: var(--db-ink); }


  /* Thirds (SPECTRA's 1/3): it stops at a third, two thirds or the whole height. The arc follows the hand either
     way and lets go on the nearest third, or away below half of one; a tap raises it a third, round to one. The share
     stands in the far corner as a Fraction, yours in italic, turning on its wheel. --third is set by the component. */
  .db-drawer[data-variant="thirds"] {
    --full: calc(100dvh - var(--db-space-7));
    max-height: var(--full); height: calc(var(--third, 1) * var(--full) / 3 - var(--pull, 0px)); min-height: var(--db-space-8);
    transition: height var(--db-andante) var(--db-spiccato), translate var(--db-andante) var(--db-spiccato), overlay var(--db-andante) allow-discrete, display var(--db-andante) allow-discrete;
  }
  .db-drawer[data-variant="thirds"][open] { translate: 0 0; }
  .db-drawer-share { position: absolute; inset-block-start: var(--db-space-4); inset-inline-end: var(--db-margin); pointer-events: none; }
  .db-drawer-share .db-fraction { font-size: var(--db-f); font-weight: 200; }
  @media (max-width: 40rem) { .db-drawer-share { inset-block-start: var(--db-space-3); } .db-drawer-share .db-fraction { font-size: var(--db-mf); } }
  .db-drawer:has(> .db-drawer-handle:is(:hover, :focus-visible, :active)) .db-drawer-share .db-fraction > :is(i, :last-child) { color: var(--db-ink); }

  /* Solid (the compositor's leads): the silence between the drawer's parts is its give. Pulling the arc takes it
     out first, so the drawer closes up and sinks as it does, set solid; only past that does it slide. Let go set
     solid and it goes; short of that, the silence springs back. Opening, it is let in. While the arc is pulled the
     script sets --solid (0 to 1: the pull over the silence it measured) and --sink (the pull beyond it). */
  .db-drawer[data-variant="solid"] {
    padding-block-end: calc(var(--db-space-7) * (1 - var(--solid, 0)));
    transition: translate var(--db-andante) var(--db-spiccato), padding-block-end var(--db-andante) var(--db-spiccato), overlay var(--db-andante) allow-discrete, display var(--db-andante) allow-discrete;
  }
  .db-drawer[data-variant="solid"][open] { translate: 0 var(--sink, 0px); }
  .db-drawer[data-variant="solid"] .db-drawer-body { gap: calc(var(--db-space-6) * (1 - var(--solid, 0))); transition: gap var(--db-andante) var(--db-spiccato); }
  .db-drawer[data-variant="solid"] .db-drawer-handle { margin-block-end: calc(var(--db-space-4) * (1 - var(--solid, 0))); transition: margin var(--db-andante) var(--db-spiccato); }
  @starting-style { .db-drawer[data-variant="solid"][open] :is(.db-drawer-body, .db-drawer-handle) { gap: 0; margin-block-end: 0; } }
  /* While the arc is held, everything follows the hand at once. */
  .db-drawer[data-pulling], .db-drawer[data-pulling] :is(.db-drawer-body, .db-drawer-handle) { transition: none; }
}
